      "태양과 달이 동쪽에서 서쪽으로 움직이는 것처럼 보이는 까닭을 알 수 있습니다.",
      "지구의의 위치를 옮겨도 우리나라 위치에서는 모든 별자리를 관찰할 수 있습니다.",
      "기차를 타고 갈 때 정지해 있는 물체가 움직이는 것처럼 보이는 까닭을 알 수 있습니다."
