     "printedExplanation": "가열 전 ㄱ과 ㄴ 모래의 온도는 같습니다. 모래를 가열하면 ㄴ보다 ㄱ에 일정한 면적의 모래에 도달하는 에너지의 양이 더 많기 때문에 ㄴ보다 ㄱ 모래의 가열 후 온도가 더 높고 온도 변화도 더 큽니다.",
     "printedRubric": null,
     "explanation": "원문은각이외조건같음을명시한다. 초기온도같음·같은시간·재질등통제에서큰각가열의단위면적입사에너지가더커서기대한온도변화가더크다. 실제임의실험결과로단정하는뜻은아니다.",
