     "printedExplanation": "초와 알코올이 탈 때 불꽃 주변이 밝아지고, 불꽃 주위에 손을 가까이 하면 따뜻한 것을 느낄 수 있습니다.",
     "printedRubric": null,
     "explanation": "초와 알코올은 연소할 때 주변을 밝히고 열을 낸다는 공통점이 있다. 초의 촛농·심지 특징은 알코올에도 공통이라고 할 수 없다. 손을 불꽃에 가까이 대어 직접 시험하는 행동으로 옮기지 않는다.",
