     "printedRubric": null,
     "explanation": "덮개 크기의 영향만 비교하려면 초기 불꽃과 초 조건이 비슷해야 한다. 점화 직후와 안정된 불꽃을 섞어 비교하면 덮개 크기 외의 조건이 함께 달라진다.",
