     "prompt": "성냥의 머리 부분을 잘라 철판 가운데에 놓고 알코올램프로 가열하였을 때의 결과로 옳은 것을 고르세요.",
     "choices": [
      "성냥의 머리 부분에 불이 붙습니다.",
      "철판의 가운데 부분만 뜨거워집니다.",
      "성냥의 머리 부분에는 아무 변화가 없습니다.",
      "철판은 뜨거워지지만 성냥의 머리 부분은 차가워집니다.",
      "철판은 가열되지 않고 성냥의 머리 부분만 뜨거워져 불이 붙습니다."
     ],
     "sourceContextBlocks": [],
