     "standards": [
      "6과15-03"
     ],
     "prompt": "다음은 전자석의 양 끝에 나침반을 놓고 스위치를 닫았을 때의 모습입니다. ㄱ과 ㄴ 중 전자석의 S극을 골라 기호를 쓰세요.",
     "choices": null,
     "sourceContextBlocks": [],
     "sourceMaterialBlocks": [
      {
       "type": "figure",
       "src": "assets/bank/c22-s62-u03/legacy-s62-electricity-s2-electromagnet-poles.png",
       "alt": "전지와 스위치가 전선으로 전자석에 연결되어 있고, 손가락으로 스위치를 누르고 있어요. 전자석 양 끝에는 ㄱ·ㄴ이 적혀 있고 양옆에 나침반이 있어요. 왼쪽 나침반 바늘의 파란 끝에 ‘S극’, 오른쪽 나침반 바늘의 붉은 끝에 ‘N극’ 설명 화살표가 이어져 있어요. ‘전지’, ‘스위치’, ‘전자석’ 이름표도 있어요."
      }
     ],
     "givens": null,
     "figure": "assets/bank/c22-s62-u03/legacy-s62-electricity-s2-electromagnet-poles.png",
     "figureNote": "전지와 스위치가 전선으로 전자석에 연결되어 있고, 손가락으로 스위치를 누르고 있어요. 전자석 양 끝에는 ㄱ·ㄴ이 적혀 있고 양옆에 나침반이 있어요. 왼쪽 나침반 바늘의 파란 끝에 ‘S극’, 오른쪽 나침반 바늘의 붉은 끝에 ‘N극’ 설명 화살표가 이어져 있어요. ‘전지’, ‘스위치’, ‘전자석’ 이름표도 있어요.",
     "visualModel": null,
     "variantRules": null,
     "parts": [],
